296	func (driver *Driver) netConfigForDevice(ctx context.Context, device string, cfg types.DeviceConfig) (netDevConfig, error) {
297		var devCfg netDevConfig
298	
299		devCfg.ipv4 = cfg.IPv4Addr
300		devCfg.ipv6 = cfg.IPv6Addr
301		devCfg.vlan = cfg.Vlan
302	
303		if cfg.NetworkConfig == "" {
304			return devCfg, nil
305		}
306	
307		netCfg, _, found := driver.resourceNetworkConfigs.Get(driver.db.ReadTxn(), ResourceNetworkConfigByName(cfg.NetworkConfig))
308		if !found {
309			return devCfg, fmt.Errorf("no network config %s found for device %s", cfg.NetworkConfig, device)
310		}
311	
312		node, err := driver.localNodeStore.Get(ctx)
313		if err != nil {
314			return devCfg, fmt.Errorf("failed to get local node: %w", err)
315		}
316	
317		targetIdx := slices.IndexFunc(netCfg.Specs, func(cfgSpec spec) bool {
318			return cfgSpec.NodeSelector.Matches(labels.Set(node.Labels))
319		})
320		if targetIdx < 0 {
321			return devCfg, fmt.Errorf("no spec matching current node found in network config %s for device %s", cfg.NetworkConfig, device)
322		}
323		targetCfg := &netCfg.Specs[targetIdx]
324	
325		devCfg.routes = make([]route, 0, len(targetCfg.IPv4Routes)+len(targetCfg.IPv6Routes))
326		devCfg.routes = append(targetCfg.IPv4Routes, targetCfg.IPv6Routes...)
327	
328		// Overwrite VLAN only when it is not configured directly in the DeviceConfiga
329		if devCfg.vlan == 0 {
330			devCfg.vlan = targetCfg.Vlan
331		}
332	
333		// just like the static IP addresses, if a pool is configured in the claim
334		// itself it takes precedence over the one in the CiliumResourceNetworkConfig
335		pool := cfg.IPPool
336		if pool == "" {
337			pool = targetCfg.IPPool
338		}
339	
340		v4FromPool := !cfg.IPv4Addr.IsValid() && pool != ""
341		v6FromPool := !cfg.IPv6Addr.IsValid() && pool != ""
342	
343		if v4FromPool || v6FromPool {
344			if v4FromPool && !driver.ipv4Enabled {
345				return devCfg, fmt.Errorf("unable to allocate an IPv4 address from resource pool %s for device %s: IPv4 support is not enabled", pool, device)
346			}
347			if v6FromPool && !driver.ipv6Enabled {
348				return devCfg, fmt.Errorf("unable to allocate an IPv6 address from resource pool %s for device %s: IPv6 support is not enabled", pool, device)
349			}
350	
351			devCfg.ipPool = pool
352	
353			v4PoolAddr, v6PoolAddr, err := driver.addrsForDevice(ctx, device, ipam.Pool(pool), v4FromPool, v6FromPool)
354	
355			// persist allocated addresses into device config even in case of error:
356			// this way the addresses will be released during rollback, if needed
357			if v4FromPool {
358				devCfg.ipv4 = netip.PrefixFrom(v4PoolAddr, targetCfg.IPv4NetMask)
359			}
360			if v6FromPool {
361				devCfg.ipv6 = netip.PrefixFrom(v6PoolAddr, targetCfg.IPv6NetMask)
362			}
363	
364			if err != nil {
365				return devCfg, err
366			}
367		}
368	
369		return devCfg, nil
370	}
